#include <vector>
#include <cmath>
#include <algorithm>

class Solution {
public:
    long long minSumSquareDiff(std::vector<int>& nums1, std::vector<int>& nums2, int k1, int k2) {
        int n = nums1.size();
        std::vector<long long> count(100001, 0);
        int max_d = 0;
        for (int i = 0; i < n; ++i) {
            int d = std::abs(nums1[i] - nums2[i]);
            count[d]++;
            if (d > max_d) {
                max_d = d;
            }
        }

        long long k = (long long)k1 + k2;

        for (int x = max_d; x > 0; --x) {
            if (count[x] == 0) continue;
            if (k >= count[x]) {
                k -= count[x];
                count[x - 1] += count[x];
                count[x] = 0;
            } else {
                count[x] -= k;
                count[x - 1] += k;
                k = 0;
                break;
            }
        }

        long long ans = 0;
        for (long long x = 1; x <= max_d; ++x) {
            if (count[x] > 0) {
                ans += count[x] * x * x;
            }
        }

        return ans;
    }
};
